export type ArticleSection={heading:string;body:string;example?:string};
export type ArticleDiagram={caption:string;lines:string[]};
export type TopicArticle={introduction:string;sections:ArticleSection[];keyTakeaways:string[];diagram?:ArticleDiagram};

export const topicArticles:Record<string,TopicArticle>={
 "dsa/arrays-hashing":{introduction:"Arrays and hash maps solve different access problems. Choosing between them begins with the operations the algorithm needs, not with which structure feels more familiar.",sections:[{heading:"Arrays preserve order",body:"An array stores elements in an indexed sequence. Reading an element by index is constant time, and a single pass is linear. Inserting or deleting near the beginning can require shifting many elements, so the operation may take linear time.",example:"Use an array when the order of items matters, when you need to scan a range, or when values naturally occupy positions such as days, scores, or matrix cells."},{heading:"Hash maps trade order for lookup",body:"A hash map converts a key into a bucket location. With a well-distributed hash function, lookup, insertion, and deletion are average O(1), though collisions and resizing affect the real cost. Most maps do not promise the same positional ordering as an array.",example:"For a Two Sum problem, store each value seen so far with its index. For a current value x, check whether target − x is already present; one pass replaces a nested search."},{heading:"Choose the structure from the invariant",body:"Use a map for membership tests, frequency counts, grouping, and remembering prior values. Use an array for stable order and indexed access. Some problems benefit from both: keep an array for output order and a set or map for fast membership."}],keyTakeaways:["Array index access is O(1); middle insertion is usually O(n).","Hash-map lookup is average O(1), with extra memory and no useful positional ordering.","Look for membership, counts, grouping, and complements as signals for a map."]},
 "dsa/complexity":{introduction:"Complexity analysis estimates how resource use grows as input size increases. It helps compare approaches and explain whether a solution will remain practical at larger input sizes.",sections:[{heading:"Describe growth, not elapsed seconds",body:"Big O focuses on an asymptotic upper growth rate and ignores machine-specific constants. O(1), O(log n), O(n), O(n log n), and O(n²) describe increasingly rapid growth for large n. Big O alone is not a benchmark: constants, memory locality, and the input distribution still matter in real systems.",example:"A loop over n values is O(n). Two separate loops each over n are O(2n), which simplifies to O(n). A loop nested inside another full n-length loop is usually O(n²)."},{heading:"Analyze the dominant work",body:"Count how often the main operations execute and keep the fastest-growing term. When an algorithm halves its remaining search range on each step, it commonly has logarithmic depth. If each level of that process touches all n elements, the total is often O(n log n).",example:"Binary search takes O(log n) comparisons. Merge sort performs O(n) merge work at each of O(log n) levels."},{heading:"Include memory and recursion",body:"Space complexity counts additional memory as input grows. State whether you are counting the input itself; interviewers often expect auxiliary space to exclude it. Recursive calls also consume stack space, which may be O(depth) even when the algorithm creates no explicit collection."}],keyTakeaways:["Simplify to the dominant growth term and state assumptions.","Distinguish auxiliary space from the input storage.","For recursion, account for both work per call and call-stack depth."]},
 "dsa/trees-graphs":{introduction:"Trees and graphs represent relationships that are not always linear. Traversal questions become easier when you identify the structure, choose a search order, and define how repeated visits are prevented.",sections:[{heading:"Trees organize hierarchical data",body:"A tree is connected and acyclic. A rooted tree gives each non-root node one parent; a binary tree gives each node at most two children. Binary search trees add an ordering rule, which can make search efficient when the tree is balanced, but an unbalanced tree can degrade to linear behavior.",example:"Use preorder, inorder, or postorder DFS when the order of processing relative to children matters. Use level-order traversal when the question asks about depth or values level by level."},{heading:"DFS and BFS answer different questions",body:"Depth-first search follows one path deeply before backtracking and uses recursion or an explicit stack. Breadth-first search explores a frontier in increasing distance from the starting node and uses a queue. BFS finds a shortest path in an unweighted graph; DFS is often simpler for reachability and component exploration.",example:"With adjacency lists, BFS and DFS are O(V + E): each vertex and edge is processed a bounded number of times."},{heading:"Cycles and disconnected components",body:"General graphs can contain cycles, so a visited set prevents repeated work and infinite loops. A traversal from one start node only covers its reachable component; to visit every vertex, loop through all vertices and start a traversal for each unvisited one."}],keyTakeaways:["Use BFS for shortest paths in unweighted graphs and level-order questions.","Use a visited set for cyclic or general graphs.","State whether the graph is directed, weighted, connected, or represented with adjacency lists."]},
 "dsa/linked-lists":{introduction:"Linked lists store elements in nodes connected by references rather than contiguous positions. Their performance depends on whether the algorithm already has a reference to the node it needs.",sections:[{heading:"Node access and mutation",body:"A singly linked node points to its successor; a doubly linked node also stores a predecessor. Finding the k-th element requires walking from a known end, so access is O(n). Once the relevant node is known, inserting or removing a link can be O(1), although finding that position may still cost O(n).",example:"A doubly linked list plus a hash map can support an LRU cache: the map finds an item quickly, and the list moves it to the most-recent position with constant-time pointer updates."},{heading:"Pointer algorithms",body:"Many linked-list problems are about changing references safely. Save the next node before redirecting a link, or the remainder of the list becomes unreachable. Dummy head nodes can simplify edge cases such as deleting the first node.",example:"To reverse a list iteratively, maintain previous, current, and next references. Redirect current.next to previous, then advance; the final previous reference is the new head."},{heading:"Fast and slow pointers",body:"Two pointers moving at different speeds can reveal structure without storing every visited node. They are useful for cycle detection, locating a midpoint, and finding a cycle's entry. The technique uses constant extra space when implemented carefully."}],keyTakeaways:["Linked lists have O(n) search and index access.","Pointer updates can be O(1) once the node is found.","Save references before changing links; use dummy nodes to reduce boundary cases."]},
 "dsa/stacks-queues":{introduction:"Stacks, queues, deques, and heaps are defined by the order in which items can be accessed. They help turn a problem's access rule into a simple and efficient data structure.",sections:[{heading:"Stack and queue order",body:"A stack removes the most recently added item (LIFO), while a queue removes the earliest added item (FIFO). Both can provide O(1) end operations. Stacks naturally model nested scopes and backtracking; queues model scheduling and breadth-first exploration.",example:"A stack checks balanced brackets by pushing opening symbols and matching each closing symbol with the most recent unmatched opener."},{heading:"Deque and monotonic structures",body:"A deque supports insertion and removal at both ends. A monotonic stack or deque maintains values in increasing or decreasing order while processing a sequence, allowing certain next-greater and sliding-window problems to run in linear time rather than comparing every pair.",example:"For a sliding-window maximum, remove smaller values from the back and expired indices from the front; the front then holds the current maximum."},{heading:"Priority queues and heaps",body:"A binary heap keeps a parent-child priority relationship, not a fully sorted order. The minimum or maximum can be read in O(1), while insertion and removal take O(log n). A heap is useful when repeatedly selecting the next most urgent item."}],keyTakeaways:["Pick stack for LIFO, queue for FIFO, and deque for both ends.","A heap supports repeated priority selection without sorting everything.","Monotonic structures are useful when each item enters and leaves at most once."]},
 "dsa/sorting-searching":{introduction:"Sorting and searching rely on ordering. Before applying a fast algorithm, make sure its preconditions hold and define exactly what the result should mean when values repeat.",sections:[{heading:"Sorting costs and guarantees",body:"Merge sort guarantees O(n log n) time and usually needs O(n) auxiliary memory. Heapsort guarantees O(n log n) and uses little extra storage, while quicksort is often fast in practice but can degrade to O(n²) with consistently poor pivots. Stability matters when equal-key items must keep their prior relative order.",example:"If records are sorted by score and then stably by name, the second stable sort preserves the score ordering among equal names."},{heading:"Binary search a monotonic condition",body:"Binary search is more general than locating a value in a sorted array. It applies whenever a predicate changes monotonically across a range, such as whether a capacity is sufficient. Each iteration must discard a portion that cannot contain the boundary.",example:"To find the first true position, maintain a false lower region and a true upper region; stop when the boundary pointers meet."},{heading:"State the interval invariant",body:"Most binary-search bugs come from mixing inclusive and exclusive bounds. Choose a closed or half-open interval, define what each endpoint means, and use an update that guarantees progress. For duplicates, decide whether to find any match, the first match, or the insertion point."}],keyTakeaways:["Binary search needs a sorted range or monotonic predicate.","Define the boundary you want before writing the loop.","Compare sort stability, worst-case time, and auxiliary space when relevant."]},
 "dsa/dynamic-programming":{introduction:"Dynamic programming solves problems by defining reusable subproblems and combining their answers. The key work is usually finding the right state and recurrence, not choosing between recursion and loops.",sections:[{heading:"Find the subproblem structure",body:"Look for overlapping subproblems: the same smaller question is reached through multiple paths. Also look for optimal substructure, where an optimal answer can be composed from optimal answers to smaller states. If subproblems do not overlap, plain divide-and-conquer may be simpler.",example:"For Fibonacci numbers, state dp[i] as the i-th value. The recurrence dp[i] = dp[i−1] + dp[i−2] avoids recomputing the same branches exponentially many times."},{heading:"Define state, recurrence, and base cases",body:"A state must record enough information to determine the future but no unnecessary history. Write the recurrence and base cases before implementation, then determine which states depend on which others. This dependency order determines a valid tabulation sequence.",example:"For a knapsack problem, dp[i][w] can mean the best value using the first i items with capacity w. The recurrence considers skipping or taking item i."},{heading:"Memoization, tabulation, and memory",body:"Memoization uses recursion and stores results on demand. Tabulation fills a table iteratively, which can avoid recursion overhead and make memory use more visible. If a state only depends on a small previous frontier, the table may be compressed after proving older values are no longer needed."}],keyTakeaways:["State precisely what each DP entry means.","Prove the recurrence and base cases cover the problem.","Optimize memory only after the dependency pattern is clear."]},
 "oop/four-pillars":{introduction:"The four OOP pillars describe ways to organize behavior and manage complexity. They are most useful when tied to a concrete design problem rather than recited as definitions.",sections:[{heading:"Encapsulation and abstraction",body:"Encapsulation keeps state and the operations that maintain it together, while limiting direct access that could break invariants. Abstraction exposes the useful contract and hides implementation details a caller does not need. One class can use both: private fields preserve valid state while public methods offer a simpler model.",example:"A bank account can keep its balance private and expose deposit and withdraw operations that validate amounts."},{heading:"Inheritance and polymorphism",body:"Inheritance lets a subtype reuse or specialize behavior from a base type. Polymorphism lets code call a shared contract while the runtime chooses the concrete implementation. Inheritance is appropriate only when the subtype can honor the expectations of the base type.",example:"A notification service can depend on a Sender interface; email and SMS implementations provide different behavior behind the same send operation."},{heading:"Use the concepts with restraint",body:"Deep inheritance hierarchies can make changes unpredictable because behavior is spread across ancestors. Prefer small interfaces and composition when behavior needs to be assembled from independent parts. The goal is clearer change boundaries, not more classes."}],keyTakeaways:["Encapsulation protects invariants; abstraction simplifies what callers see.","Polymorphism lets interchangeable implementations satisfy a common contract.","Use inheritance only for a true substitutable relationship."]},
 "oop/polymorphism":{introduction:"Polymorphism makes code work with multiple implementations through a common contract. Composition is a complementary technique for assembling behavior without forcing everything into a class hierarchy.",sections:[{heading:"Depend on behavior contracts",body:"A caller should need to know what an object can do, not the details of its concrete type. Interfaces, abstract types, or function signatures can define that contract. Runtime dispatch selects the implementation, while tests can substitute a fake or stub that follows the same rules.",example:"A checkout process can accept a payment method contract. A card processor and a wallet processor both implement charge, while checkout remains unchanged."},{heading:"Composition builds capabilities",body:"Composition gives an object collaborators that each handle a focused responsibility. It avoids coupling unrelated types through a shared parent and allows behavior to be replaced independently. Dependency injection is one way to provide those collaborators from outside.",example:"A report service can compose a formatter, data repository, and clock instead of inheriting all three responsibilities from a base report class."},{heading:"Preserve substitutability",body:"A subtype must preserve the promises callers rely on. If a subtype rejects valid base operations, changes observable behavior unexpectedly, or strengthens required preconditions, it may violate substitutability even if the code compiles."}],keyTakeaways:["Polymorphism separates callers from implementation choices.","Composition is often simpler than deep inheritance for combining behavior.","A subtype must preserve the expectations of its base contract."]},
 "oop/solid":{introduction:"SOLID is a set of design principles for managing change in object-oriented systems. Applied thoughtfully, the principles reduce coupling; applied mechanically, they can add unnecessary layers.",sections:[{heading:"Keep responsibilities cohesive",body:"Single Responsibility asks a module to have one cohesive responsibility and one main reason to change. Open/Closed encourages extending stable behavior without repeatedly editing central logic. Small focused modules help isolate changes, but splitting every function into a class is not the goal.",example:"A report generator can delegate persistence, formatting, and delivery to separate collaborators so a change in output format does not modify database code."},{heading:"Protect contracts and client needs",body:"Liskov Substitution means derived types preserve the behavior expected from their base type. Interface Segregation avoids forcing clients to depend on methods they do not use. Both principles favor contracts shaped around actual callers.",example:"If a read-only client receives an interface that also requires destructive update methods, splitting the contract can prevent accidental coupling."},{heading:"Invert high-level dependencies",body:"Dependency Inversion says high-level policy should depend on abstractions rather than concrete low-level details. Dependency injection supplies implementations at the boundary, improving testability and allowing infrastructure to change without rewriting policy."}],keyTakeaways:["Use SOLID to reduce change coupling, not to maximize abstractions.","Design contracts around client needs and preserve substitutability.","Keep high-level rules independent from infrastructure details."]},
 "oop/interfaces-abstract":{introduction:"Interfaces and abstract classes both help define reusable contracts, but they serve different purposes. The decision depends on whether you need a capability declaration or shared implementation and state.",sections:[{heading:"Interfaces describe capabilities",body:"An interface specifies behavior a type agrees to provide without requiring a shared implementation hierarchy. Unrelated types can implement the same interface, which makes interfaces useful for dependency boundaries and test doubles.",example:"A storage interface could be implemented by a local file adapter in development and a cloud object store in production."},{heading:"Abstract classes share a common base",body:"An abstract class can hold shared state, constructors, and partially implemented methods while leaving selected operations to subclasses. This creates stronger coupling to the base class and can restrict how types compose multiple sources of behavior.",example:"A base parser might provide shared input validation and require subclasses to implement the actual parse operation."},{heading:"Keep the contract focused",body:"A large interface forces implementations to provide unrelated methods and forces callers to depend on capabilities they do not use. Split contracts by the operations a client actually needs. Choose the smallest abstraction that makes the dependency easier to replace or test."}],keyTakeaways:["Interfaces define capabilities; abstract classes can share state and implementation.","Prefer focused contracts shaped around callers.","Do not use inheritance solely to share a small amount of code."]},
 "oop/exceptions-design":{introduction:"Good error handling makes failures understandable and recoverable. Design patterns can help communicate structure, but the clearest solution is often a small function until real variation appears.",sections:[{heading:"Model failure at the right boundary",body:"Exceptions are appropriate when a function cannot meet its contract due to an exceptional condition. Catch an exception where the program can recover, add useful context, or translate it into a meaningful response. Avoid swallowing errors or logging the same error at every layer.",example:"A repository may throw a storage error; an HTTP controller can map it to a safe response while retaining the underlying cause in server logs."},{heading:"Patterns express recurring structure",body:"Strategy packages interchangeable algorithms behind a common interface. Factory centralizes construction choices. Observer notifies subscribers about events. These patterns are useful when the design has the corresponding variation or communication need.",example:"Choose a tax calculation strategy by region rather than scattering region-specific conditionals across a checkout workflow."},{heading:"Avoid pattern-first design",body:"A pattern can add indirection, state, and more places to debug. Start with the simplest design that supports the current requirements, then introduce a pattern when the same structural problem recurs or the implementation must vary cleanly."}],keyTakeaways:["Catch failures where recovery or translation is meaningful.","Preserve diagnostic context without exposing internals to users.","Use a pattern to solve a real recurring design pressure."]},
 "dbms/normalization":{introduction:"Normalization organizes relational data so each fact is represented consistently. It reduces update anomalies, but database design still depends on the application's read and write patterns.",sections:[{heading:"Functional dependencies guide design",body:"A functional dependency means one attribute or set of attributes determines another. Candidate keys identify rows, and normalization rules use dependencies to decide whether attributes belong together. The goal is to avoid storing the same fact in many places where updates can disagree.",example:"If a department name is determined by department ID, storing that name on every employee row duplicates a fact and allows inconsistent spellings."},{heading:"The common normal forms",body:"First Normal Form requires values to be atomic for the chosen relational model. Second Normal Form removes partial dependencies on part of a composite key. Third Normal Form removes transitive dependencies of non-key attributes on a key. BCNF strengthens the determinant condition for every nontrivial dependency.",example:"Move department details into a Department table keyed by department ID, then reference that key from Employee."},{heading:"Balance normalization with workload",body:"Normalized schemas make writes and constraints easier to reason about but can require joins for reads. Denormalization may be reasonable for measured read bottlenecks, as long as the system has a plan to keep duplicated values consistent."}],keyTakeaways:["Identify keys and functional dependencies before splitting tables.","Normalization prevents insert, update, and delete anomalies.","Denormalize only as a deliberate, measured trade-off."]},
 "dbms/acid":{introduction:"Transactions group operations into a logical unit and define how failures and concurrent work are handled. ACID is a useful model for evaluating whether a database operation is reliable.",sections:[{heading:"The four guarantees",body:"Atomicity means all operations in a transaction commit or none do. Consistency means constraints remain satisfied. Isolation controls what concurrent transactions can observe. Durability means committed changes survive failures according to the database's guarantees.",example:"A bank transfer should subtract from one account and add to another in the same transaction so a crash cannot leave only one side committed."},{heading:"Isolation and anomalies",body:"Weaker isolation can permit anomalies such as dirty reads, non-repeatable reads, or phantom rows. Stronger isolation reduces some anomalies but can increase locking, retries, or contention. The exact guarantees and names vary by database engine.",example:"Two concurrent bookings may both see one seat as available. A transaction with an appropriate constraint or locking strategy ensures only one booking succeeds."},{heading:"Keep boundaries purposeful",body:"Use transactions around operations that must succeed or fail together. Keep them short, avoid long user interactions inside them, and handle serialization conflicts or deadlocks with bounded retries when safe."}],keyTakeaways:["ACID describes reliable transaction behavior.","Isolation level determines which concurrency anomalies are possible.","Transactions should be short and match one logical unit of work."]},
 "dbms/indexes":{introduction:"Indexes are auxiliary data structures that help a database find or order rows efficiently. They improve selected reads but increase storage use and write cost.",sections:[{heading:"How an index helps",body:"A B-tree index keeps keys in an ordered structure so equality and range predicates can locate a relevant portion without scanning every row. Other index types support different access patterns, such as full-text or spatial search. The optimizer chooses whether the index is worthwhile for a particular query.",example:"An index on (customer_id, created_at) can support queries filtering by customer and ordering that customer's rows by date."},{heading:"Selectivity and column order",body:"An index is most useful when it narrows the candidate rows enough to justify its lookup and table access cost. In a composite index, leading-column order matters: an index on (A, B) commonly supports filters on A or A and B, but not necessarily filters on B alone.",example:"For a query filtering on status and then date, compare the data distribution and query plan before choosing the composite key order."},{heading:"Measure with execution plans",body:"Use EXPLAIN or the engine's equivalent to inspect scan types, estimated rows, actual rows, sorting, and join strategies. Too many indexes slow writes and make maintenance harder, so remove unused indexes when evidence supports doing so."}],keyTakeaways:["Indexes accelerate access patterns they are designed to support.","Composite index column order matters.","Use query plans and workload measurements to guide index choices."]},
 "dbms/joins":{introduction:"Relational joins combine rows according to relationships between tables. To reason about a query, track what happens to unmatched rows and how many matches each row can have.",sections:[{heading:"Join types define row preservation",body:"An inner join keeps combinations with a matching condition. A left join preserves all left rows and supplies NULL values for unmatched right-side columns. Full outer joins preserve unmatched rows from both sides where supported.",example:"A left join from customers to orders includes customers who have never ordered; an inner join removes those customers."},{heading:"Cardinality controls duplicates",body:"If one left row matches several right rows, the output contains several combinations. This is expected relational behavior, not necessarily a bug. Aggregating after a one-to-many join can inflate counts or sums if the query does not account for that multiplication.",example:"Joining orders to order_items produces one row per item, so counting orders afterward requires COUNT(DISTINCT order_id) or a different aggregation plan."},{heading:"Filter placement matters",body:"A condition on the optional side of a left join placed in WHERE can remove rows where that side is NULL, making the result behave like an inner join. Put matching criteria in ON when unmatched rows must stay in the result."}],keyTakeaways:["Choose joins based on which unmatched rows must remain.","Check one-to-many cardinality before aggregating.","Understand whether a filter belongs in ON or WHERE."]},
 "dbms/keys-constraints":{introduction:"Keys define identity and relationships; constraints express rules that every writer must obey. Putting integrity rules in the database protects data even when it is written outside the main application.",sections:[{heading:"Identify rows and relationships",body:"A primary key is the selected identifier for each row. Candidate keys are minimal sets of attributes that uniquely identify a row. A foreign key references a key in another table and encodes a relationship that the database can enforce.",example:"An order may have an order_id primary key and a customer_id foreign key referencing Customer."},{heading:"Constraints guard valid states",body:"NOT NULL requires a value, UNIQUE prevents duplicate values, CHECK validates a condition, and foreign keys require a referenced row. Constraints apply consistently across concurrent requests and administrative scripts.",example:"A CHECK constraint can reject negative quantities even if one application endpoint forgets its input validation."},{heading:"Choose stable identifiers",body:"Natural keys come from domain data such as an email address; surrogate keys are generated identifiers. Natural values can change or have privacy implications, while generated IDs require an additional unique constraint for natural business identifiers."}],keyTakeaways:["Use primary keys for row identity and foreign keys for relationships.","Database constraints protect invariants across all writers.","Choose identifiers based on stability and domain semantics."]},
 "dbms/isolation-locking":{introduction:"Concurrent transactions need rules for coordinating reads and writes. Isolation levels and locking strategies determine which anomalies can occur and how much concurrency the database can preserve.",sections:[{heading:"Locks coordinate conflicting work",body:"A shared lock commonly allows compatible reads, while an exclusive lock protects modifications. Databases may lock rows, pages, or ranges, and may also use multiversion concurrency control to let readers observe snapshots without blocking writers.",example:"An update may hold an exclusive lock until commit so another transaction cannot silently overwrite the same row at the same time."},{heading:"Isolation defines observable behavior",body:"Read Committed prevents dirty reads but can allow repeated reads to differ. Repeatable Read and Serializable offer stronger guarantees, with exact phantom behavior depending on the engine. Serializable aims to make concurrent results equivalent to a serial ordering, sometimes by aborting transactions.",example:"A balance check followed by a withdrawal can race with another withdrawal unless the design uses an atomic update, constraint, or suitable transaction isolation."},{heading:"Choose optimistic or pessimistic control",body:"Pessimistic locking reserves a resource before changes, useful when conflicts are common. Optimistic concurrency allows work to proceed and detects conflicts at commit or through a version field, useful when conflicts are uncommon."}],keyTakeaways:["Know which anomalies the selected isolation level permits.","Lock duration and scope affect contention.","Use optimistic concurrency for rare conflicts and pessimistic locks when reservation is necessary."]},
 "sql/joins":{introduction:"SQL joins let a query combine information from related tables. The correct choice depends on the result rows the question requires, especially when related data may be missing or one-to-many.",sections:[{heading:"Use the join that preserves the intended rows",body:"INNER JOIN returns matching combinations. LEFT JOIN keeps every row from the left table, even without a match. CROSS JOIN returns every pair and can grow rapidly. Join conditions should describe the relationship, not merely connect columns with similar names.",example:"To find customers with no orders, left join to orders and filter for a NULL order key, or use NOT EXISTS."},{heading:"Avoid accidental multiplication",body:"A join can produce multiple rows for one entity when several related records match. That behavior can make COUNT and SUM values larger than expected. Before aggregation, reason about the grain: what one output row represents.",example:"If a customer has three orders and five support tickets, joining both child tables can create fifteen combinations for that customer."},{heading:"Prefer explicit and readable SQL",body:"Use explicit JOIN syntax and qualify column names. EXISTS is often clearer when only existence matters; it avoids returning duplicate outer rows due to multiple matches."}],keyTakeaways:["Know which side of an outer join must be preserved.","Identify the grain and cardinality before aggregating.","Use EXISTS when the question is only whether a match exists."]},
 "sql/aggregation":{introduction:"Aggregation summarizes groups of rows. Correct SQL depends on knowing when row filters run, how NULL values are treated, and what one group represents.",sections:[{heading:"Group at the required grain",body:"GROUP BY produces one result per distinct combination of grouping expressions. Every selected expression must either be grouped or aggregated under standard SQL rules. The chosen columns define the grain of the result.",example:"Grouping sales by month and region produces one row per month-region pair, not one row per order."},{heading:"WHERE and HAVING",body:"WHERE filters input rows before groups are formed. HAVING filters the resulting groups using aggregate conditions. Using HAVING for a simple row-level condition may do extra work and obscure the intended logic.",example:"Use WHERE order_date >= a boundary, then GROUP BY customer_id and HAVING SUM(amount) > a threshold."},{heading:"NULL and count semantics",body:"COUNT(*) counts rows, including rows where some columns are NULL. COUNT(expression) counts non-NULL results. SUM and AVG ignore NULL inputs in common SQL engines, so understand how missing data should affect the answer."}],keyTakeaways:["The GROUP BY list defines the output grain.","Filter rows with WHERE and groups with HAVING.","Understand how aggregate functions treat NULL values."]},
 "sql/window-functions":{introduction:"Window functions calculate over related rows without collapsing them into one row per group. They are useful for ranking, running totals, comparisons to prior rows, and top-N-per-group queries.",sections:[{heading:"Partition, ordering, and frame",body:"PARTITION BY divides rows into independent windows. ORDER BY defines the sequence within each window. A frame clause chooses which surrounding rows contribute to a calculation; defaults can surprise when ties or running aggregates are involved.",example:"A running sum can partition by account, order by transaction time, and use a frame from the start of the partition through the current row."},{heading:"Ranking functions differ",body:"ROW_NUMBER assigns a unique sequence even when values tie. RANK gives tied rows the same rank and leaves gaps after them. DENSE_RANK gives tied rows the same rank without gaps. Choose based on whether ties should expand the result set.",example:"For exactly one latest order per customer, ROW_NUMBER with a deterministic secondary sort is appropriate."},{heading:"Keep row identity",body:"Unlike GROUP BY, a window function preserves each row and adds a computed value. This makes it possible to filter by a ranking in an outer query or CTE while still returning the original row's columns."}],keyTakeaways:["PARTITION BY creates independent groups; ORDER BY sets sequence.","Choose ranking behavior intentionally for ties.","Windows preserve rows while computing across neighboring rows."]},
 "sql/subqueries-ctes":{introduction:"Subqueries and common table expressions let SQL express one query in terms of another. They can improve clarity, but the query plan determines the actual execution cost.",sections:[{heading:"Subqueries return different shapes",body:"A scalar subquery returns one value, an IN subquery returns a set, and a derived table acts as a temporary relation in the FROM clause. A correlated subquery refers to columns from an outer row; the optimizer may transform it, but its logical relationship can be expensive if not optimized.",example:"Use EXISTS to check for at least one matching row without needing to return the related table's columns."},{heading:"CTEs name logical steps",body:"A WITH clause gives a query result a name, helping break a large query into stages. Recursive CTEs can represent hierarchical traversal in databases that support them. Whether a CTE is materialized or inlined depends on the engine and query.",example:"A CTE can first calculate monthly revenue and then rank months, making each stage easier to inspect."},{heading:"Optimize from evidence",body:"Different syntactic forms may produce the same plan, or they may not. Inspect the execution plan, row estimates, and actual runtime rather than assuming a CTE or subquery is always faster."}],keyTakeaways:["Use subqueries for nested values and existence checks.","CTEs make multi-stage SQL easier to read and may support recursion.","Check the engine's plan before making performance claims."]},
 "sql/sql-data-integrity":{introduction:"A schema is part of a database's correctness contract. Appropriate types and constraints prevent invalid values from becoming persistent data, while parameterization keeps user input separate from executable query text.",sections:[{heading:"Choose types that model the domain",body:"Use date types for dates, numeric types for quantities and money, and bounded text types where appropriate. Type choice affects comparison, sorting, validation, storage, and the ways the database can optimize a query.",example:"Store a timestamp as a timestamp rather than a formatted string so range comparisons and timezone handling are explicit."},{heading:"Enforce invariants in the schema",body:"NOT NULL, UNIQUE, CHECK, and foreign-key constraints encode rules close to the data. Application validation improves user feedback, but database validation remains necessary because data can arrive from many writers.",example:"A unique constraint on normalized email prevents two concurrent signup requests from creating the same account."},{heading:"Separate values from SQL syntax",body:"Parameterized queries pass values as data instead of concatenating them into SQL text. This prevents input from changing the query structure and also helps the database reuse query plans."}],keyTakeaways:["Select types that reflect real domain values.","Use constraints to protect integrity across all clients.","Always parameterize untrusted values in SQL queries."]},
 "os/process-threads":{introduction:"Processes and threads are execution abstractions provided by an operating system. Their differences in memory sharing and isolation affect performance, reliability, and synchronization needs.",sections:[{heading:"Process isolation",body:"A process typically has its own virtual address space and operating-system resources. This boundary limits accidental memory interference, but communicating between processes requires mechanisms such as pipes, sockets, or shared memory.",example:"A browser can isolate tabs or renderer processes so a failure in one page is less likely to corrupt another page's memory."},{heading:"Threads share process resources",body:"Threads within a process share code and heap memory, which makes data exchange inexpensive. Each thread still has its own stack and execution state. Shared mutable data introduces races unless operations are synchronized.",example:"A server may use a worker pool to process requests, but shared caches and counters need clear concurrency rules."},{heading:"Choose a concurrency model",body:"Processes provide stronger fault containment; threads can reduce communication cost. Both have scheduling and coordination overhead. The right choice depends on whether work is I/O-bound or CPU-bound, the runtime, and how much isolation is needed."}],keyTakeaways:["Processes have separate address spaces; threads share process memory.","Shared memory is efficient but requires synchronization.","Choose based on isolation, workload, and communication costs."]},
 "os/deadlocks":{introduction:"A deadlock occurs when a group of processes cannot progress because each waits for a resource held by another. Understanding the conditions helps design prevention or recovery strategies.",sections:[{heading:"Four conditions must coexist",body:"Deadlock requires mutual exclusion, hold-and-wait, no preemption, and circular wait. Mutual exclusion means a resource cannot be shared; hold-and-wait means a process retains resources while waiting; no preemption prevents forcibly reclaiming them; circular wait forms a cycle.",example:"Two threads can deadlock if thread A holds lock 1 and waits for lock 2 while thread B holds lock 2 and waits for lock 1."},{heading:"Prevention, avoidance, and detection",body:"Prevention structures the system so at least one condition cannot hold. Avoidance evaluates whether allocations preserve a safe state. Detection allows deadlocks and searches for them, after which the system may abort or roll back work.",example:"Enforcing a global order for acquiring locks removes circular wait and is a practical prevention technique."},{heading:"Deadlock is not starvation",body:"A deadlocked process waits forever because progress depends on another blocked process. Starvation occurs when a process is repeatedly denied service while other work continues. Fair queues or aging can reduce starvation."}],keyTakeaways:["Deadlock requires all four Coffman conditions.","Consistent global lock ordering prevents circular wait.","Distinguish deadlock from starvation and livelock."]},
 "os/scheduling":{introduction:"CPU scheduling decides which runnable process or thread gets processor time. Different algorithms balance response time, throughput, fairness, and overhead in different ways.",sections:[{heading:"Common algorithms",body:"First-Come First-Served is simple but a long job can delay short ones. Shortest Job First can minimize average waiting time when burst lengths are known. Round Robin assigns a time slice to each runnable task, improving interactive responsiveness.",example:"A very large Round Robin quantum behaves more like FCFS; an extremely small quantum increases context-switch overhead."},{heading:"Priorities and fairness",body:"Priority scheduling selects more important work first, but low-priority tasks may starve. Aging raises priority as a task waits. Real-time systems may use deadlines and scheduling policies with guarantees about when work must run.",example:"A user-interface thread may receive priority to keep an application responsive, while background tasks get remaining CPU time."},{heading:"Measure the outcome",body:"Waiting time measures time spent queued; turnaround time spans submission through completion; response time measures delay until the first response. Throughput counts completed jobs per time period. A scheduling policy should be evaluated against the workload and goal."}],keyTakeaways:["No scheduler is best for every workload.","Round Robin improves fairness and responsiveness through time slices.","State which metric the algorithm optimizes."]},
 "os/virtual-memory":{introduction:"Virtual memory gives each process a protected address space that the operating system maps onto physical memory. Paging makes that mapping flexible and supports demand loading.",sections:[{heading:"Pages and page tables",body:"A virtual address is divided into a page number and offset. A page table maps the virtual page to a physical frame and stores permissions and status. A translation lookaside buffer (TLB) caches recent mappings so address translation is fast.",example:"If a page is not present in memory, a memory access may trap into the kernel so the OS can load it from storage."},{heading:"Page faults and replacement",body:"A page fault is not always an error: it can be a normal demand-paging event. The OS may load a page from a file or swap area, update mappings, and resume the instruction. If physical memory is full, a replacement policy chooses what to evict.",example:"Locality of reference means recently or nearby used pages are likely to be used again, which helps page caches work effectively."},{heading:"Thrashing and working sets",body:"If active workloads need more pages than memory can hold, the system may repeatedly fault and spend more time moving pages than executing. Reducing concurrency, adding memory, or improving locality can help."}],keyTakeaways:["Virtual memory separates process addresses from physical frames.","Page faults may be normal or indicate invalid access.","Excessive page faults can cause thrashing and collapse performance."]},
 "os/synchronization":{introduction:"Synchronization primitives coordinate concurrent access to shared state. Correct use depends on protecting invariants and minimizing the time work is blocked.",sections:[{heading:"Mutexes and semaphores",body:"A mutex provides exclusive access to a critical section and usually has ownership: the thread that locks it should unlock it. A semaphore maintains a permit count and can allow a fixed number of concurrent users or signal that an event occurred.",example:"A semaphore initialized with five permits can limit concurrent access to a pool of five connections."},{heading:"Condition variables",body:"A condition variable lets threads sleep until shared state may satisfy a condition. The condition is checked while holding the associated lock and should be rechecked in a loop after waking because wakeups can be spurious or another thread may consume the resource first.",example:"A producer signals a consumer after adding an item; the consumer loops until the queue is non-empty before removing it."},{heading:"Avoid lock hazards",body:"Long critical sections reduce concurrency. Lock ordering can prevent deadlock, and immutable data or message passing can reduce shared-state coordination. Avoid holding a lock while waiting on slow I/O or calling unknown code."}],keyTakeaways:["A mutex protects exclusive access; a semaphore controls permits or signals.","Always recheck condition-variable predicates in a loop.","Short critical sections reduce contention and deadlock risk."]},
 "os/filesystem-io":{introduction:"A file system turns persistent storage into named files and directories. The operating system also manages buffering and the path from an application's write call to durable media.",sections:[{heading:"Names, metadata, and blocks",body:"A directory maps names to file metadata. Metadata commonly includes size, ownership, permissions, timestamps, and references to data blocks. File systems choose allocation and indexing strategies to balance sequential access, random access, and space efficiency.",example:"A filesystem may use inodes or a similar structure to store metadata separately from directory names."},{heading:"Buffered and asynchronous I/O",body:"Buffering groups small operations and can improve throughput, while asynchronous interfaces let applications continue while I/O is pending. These abstractions do not remove device latency; they change how work is queued and completed.",example:"A server can asynchronously wait for a disk read while its event loop handles other ready requests."},{heading:"Durability and failure",body:"A write may first reach an operating-system or device cache rather than stable media. Applications that require durability may need synchronization calls, and correctness depends on ordering data and metadata writes as well as hardware behavior."}],keyTakeaways:["File systems map names and metadata to persistent data blocks.","Buffering improves throughput but changes when writes reach devices.","A successful write is not always a durability guarantee."]},
 "networks/osi-tcpip":{introduction:"Layered network models organize responsibilities such as addressing, transport, and application protocols. They are conceptual tools for troubleshooting, even though real implementations do not always fit a layer diagram perfectly.",sections:[{heading:"OSI and TCP/IP layers",body:"OSI describes seven layers: physical, data link, network, transport, session, presentation, and application. The common TCP/IP model groups functionality into link, internet, transport, and application layers. Protocols at one layer use services offered below.",example:"Ethernet handles local link delivery, IP routes between networks, TCP provides reliable transport, and HTTP defines web request semantics."},{heading:"Encapsulation",body:"As data moves down a network stack, each layer adds its own header or framing information. The receiver removes those layers in reverse order. This allows each layer to interpret the fields it owns without needing every application to implement physical transmission.",example:"An HTTP message is carried in a TCP segment, which is carried in an IP packet, which is carried in a link-layer frame."},{heading:"Use the model to troubleshoot",body:"A useful diagnostic question is which layer owns the failing behavior: link connectivity, IP reachability, transport connection, TLS negotiation, or application response. The models guide investigation but should not replace packet traces or system evidence."}],keyTakeaways:["IP handles network addressing and routing; TCP/UDP are transport protocols.","Encapsulation adds protocol information at each layer.","Layer models are helpful for locating failures."]},
 "networks/tcp-udp":{introduction:"TCP and UDP are transport protocols with different delivery semantics. Applications choose based on whether they need ordered reliable delivery, low overhead, or custom control over loss and retransmission.",sections:[{heading:"TCP provides a reliable byte stream",body:"TCP establishes a connection, numbers bytes, retransmits lost data, and delivers bytes in order. It also uses flow control to protect the receiver and congestion control to adapt to network load. TCP does not preserve application message boundaries.",example:"If an application writes two messages, the receiver may read them in one chunk or several; the protocol must frame messages itself."},{heading:"UDP sends independent datagrams",body:"UDP sends datagrams without guaranteeing delivery, ordering, or duplicate suppression. Its simplicity allows applications to define their own reliability or tolerate loss. Lower protocol overhead does not guarantee lower end-to-end latency in every network.",example:"Real-time voice may prefer a late or missing audio packet to waiting for retransmission of stale data."},{heading:"Choose according to the application",body:"File transfer and web traffic generally benefit from reliable ordered delivery. Real-time media, telemetry, and some request-response protocols may use UDP with application-level safeguards. Modern protocols can combine datagram transport with encryption and reliability features."}],keyTakeaways:["TCP is reliable and ordered but exposes a byte stream.","UDP preserves datagram boundaries but does not guarantee delivery.","Network behavior and application needs matter more than slogans about speed."]},
 "networks/http-dns":{introduction:"A web request depends on naming, transport, security, and application protocols working together. Following the request path is a practical way to understand latency and diagnose failures.",sections:[{heading:"DNS resolves a name",body:"DNS maps hostnames to records such as A or AAAA addresses, often through recursive resolvers and caches. TTL values control how long answers may be reused. DNS may also return multiple records or direct clients through service infrastructure.",example:"A stale cached DNS result can cause one client to reach an old server after a migration while other clients already reach the new address."},{heading:"HTTPS protects HTTP",body:"HTTP defines methods, headers, status codes, and message semantics. HTTPS carries HTTP through TLS, which authenticates the server and protects confidentiality and integrity in transit. Certificate validation is essential; encryption without verifying the peer can still allow interception.",example:"A browser validates that the certificate chain is trusted and that the requested hostname matches the certificate."},{heading:"Trace the complete request",body:"A browser can consult its cache, resolve the host, reuse or establish a TCP or QUIC connection, negotiate security, send a request, and process the response. DNS, connection setup, server processing, and resource loading can each contribute to page latency."}],keyTakeaways:["DNS resolves names and caches answers according to TTLs.","HTTPS combines HTTP with authenticated, encrypted transport.","Break request latency into lookup, connection, server, and response work."]},
 "networks/routing-subnets":{introduction:"IP addressing identifies network interfaces, while routing moves packets toward their destination across multiple networks. Subnets and routing tables determine where the next hop should be.",sections:[{heading:"Addresses and prefixes",body:"An IP address includes a network prefix and host portion. A subnet mask or prefix length defines how many leading bits identify the network. IPv4 has limited address space; IPv6 expands it and changes some operational conventions.",example:"A host sends directly to another address in its local subnet; for a remote subnet, it sends the packet to a router."},{heading:"Routers and forwarding",body:"Routers consult forwarding or routing tables to choose a next hop. A route may be learned dynamically or configured statically. Switches typically forward frames within a link using link-layer addresses, while routers connect IP networks.",example:"The default gateway is the router a host uses when the destination is outside its directly connected network."},{heading:"NAT and practical trade-offs",body:"Network Address Translation rewrites address and often port information between address spaces. It helps conserve IPv4 addresses and connect private networks, but complicates inbound connectivity and is not itself a complete security control."}],keyTakeaways:["Prefix length divides network and host bits.","Routers forward between IP networks; switches forward within a link.","NAT changes addressing but does not replace security policy."]},
 "networks/tls-ports":{introduction:"Transport ports let one host run many networked applications, and TLS protects application data across an untrusted network. Together they connect a network endpoint to a secure application session.",sections:[{heading:"Ports and sockets",body:"A port is a transport-layer identifier for an application endpoint. An IP address, port, and transport protocol together describe an endpoint; a connection is commonly identified by source and destination endpoints. Well-known ports are conventions, not proof of which program is actually listening.",example:"A client might connect from an ephemeral source port to a server's HTTPS port 443 over TCP."},{heading:"TLS handshake and trust",body:"During a TLS handshake, peers agree on cryptographic parameters and establish session keys. The server typically presents a certificate; the client validates the certificate chain, hostname, validity, and trust policy before relying on the identity.",example:"A hostname mismatch should cause a browser warning even if the certificate is signed by a trusted authority."},{heading:"Security properties",body:"TLS provides confidentiality and integrity in transit and can authenticate the server. Client authentication can also be configured. TLS does not protect compromised endpoints, unsafe application logic, or data after it is decrypted."}],keyTakeaways:["A socket endpoint combines address, port, and transport protocol.","Certificate validation is part of authentication, not an optional extra.","TLS protects data in transit, not every layer of the system."]},
 "system-design/scalability":{introduction:"Scalability is the ability to handle growth in traffic or data while meeting performance and reliability goals. A good design starts with measurements and workload assumptions rather than adding infrastructure by default.",sections:[{heading:"Vertical and horizontal scaling",body:"Vertical scaling increases resources on one machine and can be operationally simple, but hardware has limits and may remain a single failure domain. Horizontal scaling adds instances and distributes work, which requires load balancing and careful handling of shared state.",example:"A stateless web tier can add instances behind a load balancer, while a database may need a separate scaling strategy."},{heading:"Find the bottleneck",body:"Measure throughput, latency percentiles, errors, and saturation across CPU, memory, storage, network, and dependencies. A system's slowest constrained component limits overall capacity. Scale or optimize the bottleneck, then measure again because it may move.",example:"Adding web servers will not fix a database that is already saturated by unindexed queries."},{heading:"Capacity and elasticity",body:"Estimate request rates, payload sizes, and growth patterns. Elastic systems can add and remove capacity with demand, but autoscaling needs useful signals, warm-up time, and limits that avoid runaway cost."}],keyTakeaways:["Scale the measured bottleneck, not the most visible component.","Horizontal scale introduces coordination and shared-state questions.","Define performance and reliability targets before choosing architecture."]},
 "system-design/caching":{introduction:"Caching stores reusable results closer to the requester to reduce latency and backend work. The difficult part is deciding how long data remains valid and how updates propagate.",sections:[{heading:"Cache placement and keys",body:"Caches can exist in browsers, CDNs, application processes, or shared services. A cache key must include every input that changes the response, such as user identity, locale, or query parameters, or one user's result may be incorrectly reused for another.",example:"A public product image may use a long-lived CDN cache, while a personalized account balance needs strict freshness and authorization boundaries."},{heading:"Freshness and invalidation",body:"TTL expiry is simple but allows bounded staleness. Explicit invalidation can improve freshness but must handle races and failures. Stale-while-revalidate can serve a recent value while refreshing it in the background.",example:"After updating a product price, invalidate its cache key or use versioned keys so new requests do not keep receiving the old price."},{heading:"Load balancing",body:"A load balancer routes traffic across healthy service instances using algorithms such as round robin or least connections. Health checks, connection draining, and session affinity choices affect deployments and failure handling."}],keyTakeaways:["Define cache keys, freshness, and invalidation together.","Personalized data requires authorization-aware cache boundaries.","Load balancing distributes traffic and removes unhealthy instances from rotation."]},
 "system-design/availability":{introduction:"Availability means a service is usable when clients need it. Resilient design assumes individual components will fail and prevents a local problem from cascading through the whole system.",sections:[{heading:"Redundancy and failure domains",body:"Multiple instances can tolerate a machine failure, but replicas in the same region or network may share a failure domain. Redundancy helps only when failover paths are tested and dependencies do not all fail together.",example:"Deploying replicas across separate availability zones can reduce the impact of a zone outage, provided traffic routing and data replication are also ready."},{heading:"Timeouts, retries, and circuit breakers",body:"Every network call needs a bounded timeout. Retries can recover transient failures but should use limits and backoff to avoid amplifying load. Circuit breakers stop repeated calls to a failing dependency and allow it time to recover.",example:"Retry an idempotent read with exponential backoff and jitter; do not blindly repeat a payment without a deduplication key."},{heading:"Graceful degradation",body:"When optional dependencies fail, a service may return cached or partial results rather than failing completely. Bulkheads isolate resource pools so one slow dependency cannot consume every worker."}],keyTakeaways:["Redundancy must span independent failure domains.","Bound timeouts and retries; make repeated operations safe.","Degrade optional features to preserve core service behavior."]},
 "system-design/data-partitioning":{introduction:"Replication and partitioning distribute data across nodes for availability, read capacity, or storage scale. They solve different problems and introduce consistency and operational trade-offs.",sections:[{heading:"Replication copies data",body:"A primary may accept writes and replicate changes to followers. Synchronous replication waits for acknowledgements and can improve durability at the cost of write latency; asynchronous replication reduces latency but permits lag and possible loss of recent writes during failures.",example:"A read from a lagging replica may not immediately show a user's just-committed update, so some workflows need read-your-writes behavior."},{heading:"Partitioning divides data",body:"Sharding assigns different records to different nodes using a partition key. A useful key distributes load while aligning with common queries. Poor distribution creates hot partitions, and changing the key later can require expensive data movement.",example:"Partitioning by a high-cardinality customer key may distribute data better than partitioning by a small set of status values."},{heading:"Plan for cross-node operations",body:"Joins, transactions, and aggregations across partitions are more complex and may require fan-out. Rebalancing, backups, schema changes, and failure recovery are part of the design rather than later operational details."}],keyTakeaways:["Replication makes copies; partitioning splits different data across nodes.","Replication mode controls freshness and write latency trade-offs.","Partition keys should avoid hotspots and support access patterns."]},
 "system-design/queues-events":{introduction:"Queues decouple producers from consumers and let a system process work asynchronously. They smooth bursts, but reliable processing requires explicit delivery and failure semantics.",sections:[{heading:"Buffer work between services",body:"A queue can absorb a temporary spike while consumers process at a sustainable rate. Producers and consumers can scale independently, and the queue provides a place to observe backlog. If arrivals exceed processing capacity for too long, the backlog still grows without bound.",example:"An API can enqueue report generation and return quickly while background workers create the report."},{heading:"Delivery guarantees and idempotency",body:"At-most-once delivery may lose messages; at-least-once delivery can repeat them; exactly-once claims usually depend on carefully scoped transactional or deduplication guarantees. Consumers should make side effects idempotent where possible.",example:"Store a processed event ID with a payment operation so a retry does not charge the customer twice."},{heading:"Retries, ordering, and dead letters",body:"Choose retry limits and backoff, define whether ordering matters, and route repeatedly failing messages to a dead-letter queue for inspection. Backpressure and visibility timeouts prevent consumers from taking more work than they can process."}],keyTakeaways:["Queues smooth bursts but do not create infinite capacity.","Expect duplicates under at-least-once delivery and design idempotently.","Specify retries, ordering, backlog limits, and dead-letter handling."]},
 "web-stack/javascript-event-loop":{introduction:"JavaScript combines synchronous execution with asynchronous APIs and event-loop scheduling. Understanding the call stack and queues explains why callbacks run later and why blocking work harms responsiveness.",sections:[{heading:"Call stack and event loop",body:"Synchronous JavaScript runs on a call stack. When an operation such as a timer, network request, or file operation completes, its continuation becomes eligible to run through the runtime's scheduling queues. The event loop selects ready work when the stack is clear.",example:"A long synchronous loop prevents a browser from processing input and paint callbacks until the loop finishes."},{heading:"Microtasks and tasks",body:"Promise reactions and queueMicrotask callbacks run as microtasks. Browsers generally drain the microtask queue after the current task before moving to another task such as a timer callback. A chain that continually adds microtasks can delay rendering and other tasks.",example:"A resolved Promise callback typically runs before a setTimeout callback scheduled in the same stack."},{heading:"Closures preserve lexical bindings",body:"A closure retains access to variables from the scope where a function was created. This enables callbacks and factories, but can also keep large objects alive or capture a value that changes unexpectedly. Understand whether the closure captures a binding or a copied value."}],keyTakeaways:["JavaScript callbacks run when the current stack yields.","Microtasks are generally processed before the next task.","Closures retain access to their lexical environment."]},
 "web-stack/react-state-effects":{introduction:"React components describe UI as a function of props and state. Effects connect that UI to systems outside React, such as subscriptions, timers, or browser APIs.",sections:[{heading:"State drives rendering",body:"When state changes, React schedules a render using the new value. State should be updated immutably so changes are observable and predictable. Values that can be calculated from existing props or state should usually be derived during render rather than copied into more state.",example:"If a component has a list and a search term, compute the filtered list instead of maintaining a second state variable that can become stale."},{heading:"Effects synchronize with external systems",body:"An effect runs after rendering to synchronize with something React does not own. Its dependency list describes reactive values used by the effect; cleanup removes subscriptions or cancels work before the effect reruns or the component unmounts.",example:"An effect that registers a window resize listener should remove that listener in its cleanup function."},{heading:"Avoid effects for ordinary data flow",body:"Using effects to copy props into state or calculate derived values creates extra renders and synchronization bugs. Prefer direct rendering, event handlers for user actions, and effects only for external synchronization."}],keyTakeaways:["Treat state as immutable and derive what can be derived.","Use effects for external synchronization, not every calculation.","Clean up subscriptions, timers, and other ongoing work."]},
 "web-stack/node-async":{introduction:"Node.js is built around an event-driven runtime that handles many I/O waits without dedicating a JavaScript thread to each request. This model performs well for I/O-bound work but requires care with CPU-heavy operations.",sections:[{heading:"Non-blocking I/O",body:"When JavaScript starts an asynchronous I/O operation, the runtime can continue processing other ready callbacks while the operating system or a worker pool handles the wait. When the operation completes, its callback or Promise continuation is scheduled.",example:"A server can wait for several database responses concurrently rather than blocking the entire process on each query."},{heading:"Protect the event loop",body:"Long synchronous computation blocks the event loop and delays all requests served by that process. CPU-heavy work can move to worker threads or a separate job service. Worker threads add communication and memory costs, so profile before moving work.",example:"Image resizing or a large cryptographic calculation may be better handled by a worker pool than inside a request callback."},{heading:"Middleware is an ordered pipeline",body:"Express middleware receives a request, response, and next function. Middleware can authenticate, validate, add context, handle errors, send a response, or pass control onward. Ordering matters: parsing should run before routes that need parsed bodies, and error middleware belongs in the expected position."}],keyTakeaways:["Node.js scales I/O concurrency through asynchronous work.","CPU-heavy synchronous JavaScript blocks the event loop.","Middleware order affects every request that passes through it."]},
 "web-stack/http-browser":{introduction:"The browser is both a network client and a rendering runtime. Understanding HTTP semantics, rendering stages, and storage behavior helps build responsive applications and avoid security mistakes.",sections:[{heading:"HTTP semantics",body:"Methods describe intent: GET retrieves a representation, POST submits or creates work, PUT replaces a resource, and DELETE removes it. Status codes communicate outcomes. Safe methods should not cause intended state changes, and idempotent operations can be repeated without changing their intended effect.",example:"A client can retry an idempotent PUT more safely after a network timeout than a non-idempotent payment POST without an idempotency key."},{heading:"Browser rendering",body:"The browser parses markup into a DOM and styles into a CSSOM, combines them for layout, then paints and composites pixels. JavaScript can update the DOM, but long tasks delay input and rendering. Network resources, layout shifts, and script execution all influence perceived speed.",example:"Lazy-loading below-the-fold images reduces initial network work, while reserving image dimensions prevents layout shifts."},{heading:"Client storage and trust boundaries",body:"Cookies, localStorage, and sessionStorage differ in lifetime and request behavior. Script-readable storage can be exposed by XSS; cookies can be sent automatically and need appropriate SameSite, Secure, and HttpOnly settings. Choose storage based on the authentication threat model."}],keyTakeaways:["Use HTTP method semantics and status codes consistently.","Long JavaScript tasks delay rendering and interaction.","Choose client storage with its security and request behavior in mind."]},
 "web-stack/react-rendering":{introduction:"React rendering recalculates a component's UI description when relevant inputs change. Performance work should focus on measured bottlenecks while preserving stable identity and understandable state flow.",sections:[{heading:"Render and commit",body:"A render phase calls components to calculate the next tree. React then compares it with the previous result and commits necessary changes to the DOM. A render does not mean every element is recreated in the browser.",example:"A parent can render again while React leaves an unchanged child DOM node untouched."},{heading:"Keys and identity",body:"Keys help React identify list items across insertions, removals, and reordering. Stable data IDs are preferable to array positions when order can change. An unstable key can cause state to attach to the wrong item or force unnecessary remounts.",example:"Use a todo item's database ID as its key, not its current position in the filtered list."},{heading:"Profile before memoizing",body:"Memoization can avoid repeated expensive calculations or renders when inputs remain stable, but it adds complexity and only helps in specific cases. Keep state close to its consumers, split components around clear responsibilities, and profile production-like interactions before optimizing."}],keyTakeaways:["Rendering computes a UI tree; commit updates only necessary DOM changes.","Use stable keys that represent item identity.","Use memoization when profiling shows a real benefit."]},
 "web-stack/web-security":{introduction:"Web security relies on protecting trust boundaries between users, browsers, application servers, and dependencies. Input validation is useful, but safe output handling and server-side authorization are essential too.",sections:[{heading:"Prevent cross-site scripting",body:"XSS occurs when untrusted content is interpreted as executable script in another user's browser. Escape output for its context and prefer framework APIs that render text safely. Sanitization is needed when intentionally allowing a limited set of HTML.",example:"Rendering a user comment as plain text is safer than inserting it with an unsafe HTML API."},{heading:"Protect authenticated actions",body:"CSRF abuses credentials that browsers attach automatically, commonly cookies. SameSite cookie settings, CSRF tokens, and Origin checks can reduce risk depending on the architecture. Authorization must still be checked on the server for every protected resource.",example:"A hidden button in the UI is not authorization; the API must verify the user's role and resource ownership."},{heading:"Keep secrets and data protected",body:"Use HTTPS, validate inputs at the server boundary, rate-limit sensitive operations, and keep private API keys out of frontend bundles. Least privilege limits damage if a credential or component is compromised."}],keyTakeaways:["Encode or safely render untrusted content to prevent XSS.","Protect cookie-authenticated state changes against CSRF.","Enforce authorization on the server and keep API secrets private."]}
};
